output_text:
[
  {
    "id": "pedestrian_only_single_file",
    "text": "Shopping carts are forbidden in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_single_file",
    "text": "An agent must not push a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "cartEntersSingleFileAisle": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartEntersSingleFileAisle"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever an agent parks or releases a cart, they are obliged to retrieve a cart again before the trip ends.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "park_only_in_open_spaces",
    "text": "Carts may only be parked in sufficiently wide open areas rather than in constricted aisles.",
    "abstraction": {
      "state_properties": {
        "openCartParkingSpot": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "openCartParkingSpot"
          }
        ]
      }
    }
  },
  {
    "id": "take_cart_before_leaving_cart_bay",
    "text": "After reaching the cart bay, an agent must not leave it without a cart.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)"
      },
      "events": {
        "leaveCartBayWithoutCart": {
          "pre": {
            "and": [
              "cartBay",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": {
            "not": "cartBay"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leaveCartBayWithoutCart"
    }
  },
  {
    "id": "cart_required_for_open_aisle_shelves",
    "text": "Shelf interactions from ordinary open aisles must be done with a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openShelfAisle": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {
        "shelfInteraction": {
          "pre": {
            "and": [
              "INTERACT",
              "adjShelf"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelfInteraction",
          "openShelfAisle",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_for_single_file_shelf_items",
    "text": "Shelf interactions inside single-file shelf aisles must be performed without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "shelfInteraction": {
          "pre": {
            "and": [
              "INTERACT",
              "adjShelf"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelfInteraction",
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "eastbound_wide_aisles",
    "text": "Wide horizontal aisles are one-way eastbound, so agents must not move west in them.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideHorizontalAisle",
          "W"
        ]
      }
    }
  }
]
